// Layout components using Tailwind CSS classes
// Following the premium design system

export const MainLayout = ({ children }) => (
    <div className="flex gap-8 h-full p-8">
        {children}
    </div>
);

export const InnerLayout = ({ children }) => (
    <div className="flex-1 p-8">
        {children}
    </div>
);
